// The complete squares are drawn above the coastline clip so a first tile is visible.
const mapCamera={view:{x:0,y:0,w:360,h:660},mode:'home',done:-1,lastValue:null,drag:null,painted:false,lock:false};
const mapRows=new Map();
CHILE_MAP.cells.forEach(([x,y],i)=>{const key=y+':'+(x<95?'island':'main');if(!mapRows.has(key))mapRows.set(key,[]);mapRows.get(key).push({x,i})});
const MAP_TILE_COLORS=[];
mapRows.forEach(row=>{row.sort((a,b)=>a.x-b.x);row.forEach((cell,index)=>{const stripe=row.length<=2?(index===0?0:2):Math.min(2,Math.floor(index*3/row.length));MAP_TILE_COLORS[cell.i]=['#155cb1','#ffffff','#e43f45'][stripe]})});
function applyMapView(view){const w=Math.max(16,Math.min(360,view.w)),h=Math.min(660,Math.max(24,view.h));mapCamera.view={x:Math.max(0,Math.min(360-w,view.x)),y:Math.max(0,Math.min(660-h,view.y)),w,h};const v=mapCamera.view;$('#chile-map').setAttribute('viewBox',`${v.x} ${v.y} ${v.w} ${v.h}`);$('#map-zoom-level').textContent=(360/v.w).toLocaleString('es-CL',{maximumFractionDigits:1})+'×';$('#follow-map').setAttribute('aria-pressed',String(mapCamera.mode==='follow'));$('#map-full').setAttribute('aria-pressed',String(mapCamera.mode==='full'||mapCamera.mode==='home'));$('.map-area').classList.toggle('zoomed',v.w<300);$('.map-area').classList.toggle('pannable',v.w<355)}
function applyFullView(){applyMapView({x:0,y:0,w:360,h:660})}
// Centro del area que se esta marcando: el ultimo cuadro encendido (o el primero, si aun no hay ninguno).
function progressAnchor(){const i=Math.min(999,Math.max(0,mapCamera.done-1)),[x,y]=CHILE_MAP.cells[i];const nearby=CHILE_MAP.cells.filter(([cx,cy])=>Math.abs(cy-y)<23&&(x<95?Math.abs(cx-x)<45:cx>=95));const xs=nearby.map(c=>c[0]);return{x:(Math.min(...xs)+Math.max(...xs))/2+CHILE_MAP.step/2,y,width:Math.max(46,Math.min(110,Math.max(...xs)-Math.min(...xs)+18))}}
function focusMapProgress(){mapCamera.mode='follow';mapCamera.lock=true;const a=progressAnchor();const viewport=$('.map-viewport'),ratio=(viewport.clientHeight||480)/(viewport.clientWidth||320),height=Math.min(180,a.width*ratio);applyMapView({x:a.x-a.width/2,y:a.y-height*.18,w:a.width,h:height})}
function fullMap(){mapCamera.mode='full';mapCamera.lock=false;applyFullView()}
function syncMapView(){if(mapCamera.mode==='home')return applyFullView();if(mapCamera.mode==='follow')focusMapProgress()}
// Mientras no se tome control manual, el zoom se dirige al frente del recorrido.
function zoomMap(factor){const v=mapCamera.view,w=Math.max(16,Math.min(360,v.w/factor)),h=Math.min(660,v.h*w/v.w);if(w>=355){if(mapCamera.mode==='home')applyFullView();else fullMap();return}const a=mapCamera.lock?progressAnchor():null,seen=!!(a&&a.x>=v.x&&a.x<=v.x+v.w&&a.y>=v.y&&a.y<=v.y+v.h),cx=seen?a.x:v.x+v.w/2,cy=seen?a.y:v.y+v.h/2;mapCamera.mode='free';applyMapView({x:cx-w/2,y:cy-h/2,w,h})}
function renderMapProgress(value=total()+sessionCount){const n=Math.max(0,Number(value)||0),done=Math.min(1000,Math.floor(n/1000)),saved=total(),pending=Math.max(0,n-saved);if(mapCamera.lastValue===n&&mapCamera.lastSaved===saved)return;mapCamera.lastValue=n;mapCamera.lastSaved=saved;const changed=done!==mapCamera.done,first=!mapCamera.painted;mapCamera.done=done;mapCamera.painted=true;
 $('#total').textContent=fmt(n);$('#percent').textContent=(Math.min(n,1000000)/10000).toLocaleString('es-CL',{maximumFractionDigits:2})+' % del viaje';$('#progress-bar').style.width=Math.min(100,n/10000)+'%';$('#map-cells-count').textContent=`${fmt(done)} de 1.000 cuadros iluminados`;
 const rest=n%1000;$('#map-next-cell').textContent=done>=1000?'¡Completaste el mapa de Chile!':`${fmt(rest)} / 1.000 para el próximo cuadro`;$('#map-session-note').textContent=pending?`Incluye ${fmt(pending)} daimoku de esta sesión, aún sin guardar.`:'Progreso de tus sesiones guardadas.';
 const destination=stops.find(s=>n<s.end)||stops.at(-1);$('#destination-title').textContent=destination.name;$('#destination-desc').textContent=destination.value;$('.destination small').textContent=n>=1000000?'UN MILLÓN DE POSIBILIDADES CULTIVADAS':destination.zone+' · TU ESTACIÓN ACTUAL';
 if(changed){$('#completed-tiles').innerHTML=CHILE_MAP.cells.slice(0,done).map(([x,y],i)=>`<rect class="completed-cell" data-tile="${i+1}" x="${x}" y="${y}" width="${CHILE_MAP.step}" height="${CHILE_MAP.step}" fill="${MAP_TILE_COLORS[i]}" stroke="#244b6b" stroke-width=".35"/>`).join('');const [x,y]=CHILE_MAP.cells[Math.max(0,done-1)];$('#active-tile').setAttribute('x',x-.6);$('#active-tile').setAttribute('y',y-.6);$('#active-tile').setAttribute('visibility','visible');if(first){if(mapCamera.mode==='home')applyFullView()}else{if(mapCamera.mode==='home'&&done>0)mapCamera.mode='follow';syncMapView()}}
}
function initMapControls(){const svg=$('#chile-map');svg.insertAdjacentHTML('beforeend',`<g id="completed-tiles"></g><rect id="active-tile" width="${CHILE_MAP.step+1.2}" height="${CHILE_MAP.step+1.2}" fill="none" stroke="#edac42" stroke-width="2" vector-effect="non-scaling-stroke" visibility="hidden"/>`);$('#map-in').onclick=()=>zoomMap(1.5);$('#map-out').onclick=()=>zoomMap(1/1.5);$('#map-full').onclick=fullMap;$('#follow-map').onclick=focusMapProgress;
 svg.onpointerdown=e=>{if(mapCamera.view.w>=355)return;mapCamera.drag={x:e.clientX,y:e.clientY,view:{...mapCamera.view}};svg.setPointerCapture(e.pointerId);svg.classList.add('dragging')};svg.onpointermove=e=>{if(!mapCamera.drag)return;mapCamera.mode='free';mapCamera.lock=false;const start=mapCamera.drag,b=svg.getBoundingClientRect();applyMapView({...start.view,x:start.view.x-(e.clientX-start.x)/b.width*start.view.w,y:start.view.y-(e.clientY-start.y)/b.height*start.view.h})};const stop=()=>{mapCamera.drag=null;svg.classList.remove('dragging')};svg.onpointerup=stop;svg.onpointercancel=stop;svg.onkeydown=e=>{if(['+','='].includes(e.key)){e.preventDefault();zoomMap(1.5)}else if(e.key==='-'){e.preventDefault();zoomMap(1/1.5)}else if(e.key==='0'){e.preventDefault();fullMap()}else if(e.key.toLowerCase()==='f'){e.preventDefault();focusMapProgress()}else if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();mapCamera.mode='free';mapCamera.lock=false;const v=mapCamera.view;applyMapView({...v,x:v.x+(e.key==='ArrowLeft'?-.15:e.key==='ArrowRight'?.15:0)*v.w,y:v.y+(e.key==='ArrowUp'?-.15:e.key==='ArrowDown'?.15:0)*v.h})}};
  if(typeof ResizeObserver!=='undefined')new ResizeObserver(()=>{syncMapView()}).observe($('.map-viewport'));
}
